def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    aggressive_count = 0
    weak_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 100:
                aggressive_count += 1
            if bid <= 45:
                weak_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    scarcity = 1.0 - supply_ratio

    if hp <= 2 or no_water_days >= 2:
        emergency = True
    elif hp <= 4 and no_water_days >= 1:
        emergency = True
    else:
        emergency = False

    if emergency:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
        if highest_prev >= 140:
            target = max(target, 145.0)
        return float(min(budget, target))

    if scarcity <= 0.2:
        base = DAILY_SALARY * 0.28
    elif scarcity <= 0.5:
        base = DAILY_SALARY * 0.42
    else:
        base = DAILY_SALARY * 0.62

    if highest_prev >= 140:
        target = base
        if hp <= 5 or no_water_days >= 1:
            target = max(target, DAILY_SALARY * 0.88)
    elif highest_prev >= 100:
        target = max(base, min(highest_prev * 0.72, DAILY_SALARY * 0.92))
    elif highest_prev >= 60:
        target = max(base, highest_prev + 2.5)
    elif highest_prev > 0:
        target = max(base, highest_prev + 1.5)
    else:
        target = DAILY_SALARY * 0.45

    if aggressive_count >= 2 and scarcity < 0.4 and hp >= 6 and no_water_days == 0:
        target = min(target, DAILY_SALARY * 0.33)

    if weak_count >= 2 and scarcity > 0.5:
        target = max(target, DAILY_SALARY * 0.58)

    if day >= 8:
        target += 6.0
    if hp <= 5:
        target += 8.0
    if no_water_days == 1:
        target += 10.0

    if target < 0:
        target = 0.0

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Reaction to yesterday's bidding pressure
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0.0

    # Estimate how many water units are likely needed to secure enough days.
    # With simultaneous bidding, we target a moderate share rather than maxing.
    # If supply is near 15, competition is tighter.
    supply_ratio = (supply - MIN_SUPPLY) / max(1e-9, (MAX_SUPPLY - MIN_SUPPLY))
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid: moderate, higher when supply is lower.
    base = DAILY_SALARY * (0.62 - 0.18 * supply_ratio)  # ~0.62 at low supply, ~0.44 at high supply

    # Escalation logic: if someone previously bid very high, they likely try to secure water.
    # Punish by not matching unless our HP is critical.
    if highest_prev_bid >= DAILY_SALARY * 1.15:
        if hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        else:
            target = base * 0.95  # keep moderate to avoid burning budget
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        if hp <= 3.0 or no_water_days >= 3:
            target = DAILY_SALARY * 0.78
        else:
            target = base * 1.05
    else:
        # If yesterday bids were not extreme, we can slightly undercut.
        if hp <= 2.0 or no_water_days >= 3:
            target = DAILY_SALARY * 0.85
        else:
            target = base * 0.92

    # Convert target into feasible bid given budget.
    bid = min(budget, target)

    # Ensure non-negative and avoid tiny bids that likely lose.
    min_reasonable = DAILY_SALARY * 0.25
    if bid < min_reasonable and budget >= min_reasonable:
        bid = min_reasonable

    # If budget is very low, just bid what we can.
    if budget <= 1e-9:
        return 0.0

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
